function parseFormula(f){
  var stack=[{}], i=0;
  while(i<f.length){
    var c=f.charAt(i);
    if(c==='('){ stack.push({}); i++; continue; }
    if(c===')'){
      i++;
      var num=''; while(i<f.length && /\d/.test(f.charAt(i))){ num+=f.charAt(i); i++; }
      var mult=num?parseInt(num,10):1;
      var grp=stack.pop(); var top=stack[stack.length-1];
      for(var e in grp){ top[e]=(top[e]||0)+grp[e]*mult; }
      continue;
    }
    var m=/^([A-Z][a-z]?)(\d*)/.exec(f.slice(i));
    if(m && m[1]){
      var el=m[1], cnt=m[2]?parseInt(m[2],10):1;
      var t2=stack[stack.length-1];
      t2[el]=(t2[el]||0)+cnt;
      i+=m[0].length;
      continue;
    }
    i++;
  }
  var res=stack[0];
  for(var k=1;k<stack.length;k++){ var s=stack[k]; for(var e2 in s){ res[e2]=(res[e2]||0)+s[e2]; } }
  return res;
}
function gcdInt(a,b){ a=Math.abs(Math.round(a)); b=Math.abs(Math.round(b)); while(b){ var t=b; b=a%b; a=t; } return a||1; }
function gcdList(arr){ var g=Math.abs(Math.round(arr[0])); for(var i=1;i<arr.length;i++) g=gcdInt(g,arr[i]); return g||1; }
function denomOf(v){ v=Math.abs(v); if(Math.abs(v-Math.round(v))<1e-9) return 1;
  for(var d=2; d<=1000; d++){ var p=v*d; if(Math.abs(p-Math.round(p))<1e-9) return d; } return 1; }
function lcmList(arr){ var l=1; for(var i=0;i<arr.length;i++) l=l*arr[i]/gcdInt(l,arr[i]); return l; }
function balanceEquation(eq){
  var sides=String(eq||'').split(/=>|->|→|=/);
  if(sides.length!==2) return {ok:false, reason:'方程式需包含两侧（用 = 或 -> 分隔）'};
  var left=sides[0].split('+').map(function(x){return x.replace(/\s/g,'');}).filter(Boolean);
  var right=sides[1].split('+').map(function(x){return x.replace(/\s/g,'');}).filter(Boolean);
  if(!left.length || !right.length) return {ok:false, reason:'某一侧为空'};
  var species=left.concat(right), n=species.length;
  var counts=species.map(function(sp){ return parseFormula(sp); });
  var order=[], seen={};
  counts.forEach(function(c){ for(var e in c){ if(!seen[e]){ seen[e]=1; order.push(e); } } });
  var m=order.length;
  if(m===0) return {ok:false, reason:'未识别到元素'};
  var M=[];
  for(var i=0;i<m;i++){
    var row=[];
    for(var j=0;j<n;j++){ var v=counts[j][order[i]]||0; row.push(j<left.length? v : -v); }
    M.push(row);
  }
  var A=[];
  for(var i2=0;i2<m;i2++) A.push(M[i2].slice(0,n-1).concat([-M[i2][n-1]]));
  var piv=0, where=[];
  for(var col=0; col<n-1 && piv<m; col++){
    var sel=-1;
    for(var r=piv;r<m;r++){ if(Math.abs(A[r][col])>1e-9){ sel=r; break; } }
    if(sel<0) continue;
    var tmp=A[sel]; A[sel]=A[piv]; A[piv]=tmp;
    var pv=A[piv][col];
    for(var c2=col;c2<n;c2++) A[piv][c2]/=pv;
    for(var r2=0;r2<m;r2++){
      if(r2===piv) continue;
      var fct=A[r2][col];
      if(Math.abs(fct)<1e-12) continue;
      for(var c3=col;c3<n;c3++) A[r2][c3]-=fct*A[piv][c3];
    }
    where.push(col);
    piv++;
  }
  for(var r3=piv;r3<m;r3++){
    var allZero=true;
    for(var c4=0;c4<n-1;c4++){ if(Math.abs(A[r3][c4])>1e-9){ allZero=false; break; } }
    if(allZero && Math.abs(A[r3][n-1])>1e-9) return {ok:false, reason:'无法配平（元素不守恒）'};
  }
  var sol=[]; for(var q=0;q<n-1;q++) sol.push(0);
  for(var i3=0;i3<where.length;i3++) sol[where[i3]]=A[i3][n-1];
  sol.push(1);
  var dens=[]; for(var i4=0;i4<sol.length;i4++) dens.push(denomOf(sol[i4]));
  var L2=lcmList(dens);
  var ints=[]; for(var i5=0;i5<sol.length;i5++) ints.push(Math.round(sol[i5]*L2));
  var mn=Math.min.apply(null,ints);
  if(mn<0){ for(var i6=0;i6<ints.length;i6++) ints[i6]=-ints[i6]; }
  for(var i7=0;i7<ints.length;i7++){ if(ints[i7]<=0) return {ok:false, reason:'无法求得正整数解'}; }
  var g=gcdList(ints);
  if(g>1){ for(var i8=0;i8<ints.length;i8++) ints[i8]=ints[i8]/g; }
  function fmt(list, off){
    var parts=[];
    for(var i=0;i<list.length;i++){
      var c=ints[off+i];
      parts.push((c===1?'':c)+list[i]);
    }
    return parts.join(' + ');
  }
  return {ok:true, balanced:fmt(left,0)+' = '+fmt(right,left.length), coefficients:ints};
}

var EXPORTS={parseFormula:parseFormula,balanceEquation:balanceEquation};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BalanceForgePure = EXPORTS; }
